/** → () => Promise<url> for reference/<id>/<file>, or null when it was not bundled. */
export const refLoader = (id, file) => {
  const url = REF_URLS[`../../reference/${id}/${file}`]
  return url ? () => Promise.resolve(url) : null
}
export const refCredit = (id, file) => REF_CREDITS[`${id}/${file}`] || ''
